<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import * as CANNON from 'cannon-es';

/* Deterministic seeded RNG — visual variation only, never physics placement randomness */
function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
const visRand = mulberry32(20261015);

/* ---------- Renderer / Scene ---------- */
const app = document.getElementById('app');
const renderer = new THREE.WebGLRenderer({antialias:true, powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
renderer.outputColorSpace = THREE.SRGBColorSpace;
app.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87b5d9);
scene.fog = new THREE.Fog(0x9fc3e2, 55, 140);

const pmrem = new THREE.PMREMGenerator(renderer);
scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;

const camera = new THREE.PerspectiveCamera(50, innerWidth/innerHeight, 0.1, 300);
camera.position.set(-6,5.5,11);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true; controls.dampingFactor = 0.08; controls.maxPolarAngle = Math.PI*0.49; controls.enabled = false;

const sun = new THREE.DirectionalLight(0xfff2d9, 3.2);
sun.position.set(14,24,10);
sun.castShadow = true;
sun.shadow.mapSize.set(2048,2048);
sun.shadow.camera.near = 2; sun.shadow.camera.far = 70;
sun.shadow.bias = -0.0004; sun.shadow.normalBias = 0.02;
scene.add(sun); scene.add(sun.target);
scene.add(new THREE.HemisphereLight(0xbdd7f2, 0x3a4a3a, 0.7));

/* Shared materials */
const paintMat = new THREE.MeshPhysicalMaterial({color:0xc1272d, metalness:0.85, roughness:0.32, clearcoat:1, clearcoatRoughness:0.08, envMapIntensity:1.2});
const paintDark = new THREE.MeshPhysicalMaterial({color:0x1f2937, metalness:0.7, roughness:0.45, clearcoat:0.6, envMapIntensity:0.9});
const glassMat = new THREE.MeshPhysicalMaterial({color:0x9fd8ef, metalness:0, roughness:0.06, transparent:true, opacity:0.5, envMapIntensity:1.6, clearcoat:1});
const tireMat = new THREE.MeshStandardMaterial({color:0x111214, roughness:0.95, metalness:0});
const rimMat = new THREE.MeshStandardMaterial({color:0xd7dde6, roughness:0.28, metalness:0.95});
const plasticMat = new THREE.MeshStandardMaterial({color:0x171a1f, roughness:0.8, metalness:0.2});
const lightMat = new THREE.MeshStandardMaterial({color:0xfff7cc, emissive:0xffedb5, emissiveIntensity:1.6, roughness:0.2});
const tailMat = new THREE.MeshStandardMaterial({color:0x7f1d1d, emissive:0xdc2626, emissiveIntensity:1.1, roughness:0.25});
const brickMats = [0xb5654a,0xa8553e,0xc06a4f,0x9e4f38,0xbb6248].map(c=>new THREE.MeshStandardMaterial({color:c, roughness:0.92, metalness:0.02}));
const asphaltMat = new THREE.MeshStandardMaterial({color:0x2b2f36, roughness:0.96, metalness:0});
const grassMat = new THREE.MeshStandardMaterial({color:0x4a7c3a, roughness:1});
const curbRed = new THREE.MeshStandardMaterial({color:0xd33a2c, roughness:0.8});
const curbWhite = new THREE.MeshStandardMaterial({color:0xf3f4f6, roughness:0.8});
const whiteMat = new THREE.MeshStandardMaterial({color:0xf8fafc, roughness:0.85});
const barrierMat = new THREE.MeshStandardMaterial({color:0xe5e7eb, roughness:0.5, metalness:0.35});

/* ---------- State ---------- */
let world=null, dyn=[], constraints=[], brickBodies=[], carParts=[], wheelSpinners=[];
let settings=null, paused=false, simSpeed=1, camMode='impact';
let impacted=false, driveSpeed=0, shake=0, dust=null, dustVel=[], sparks=null, sparkVel=[];
let wallX=14, carStartX=-14, chassisBody=null, frontBody=null, elapsed=0;
const FIXED=1/60; let acc=0, last=performance.now();

const $=id=>document.getElementById(id);
function readSettings(){
  const n=(id,d)=>{const v=parseFloat($(id).value); return Number.isFinite(v)?v:d};
  const i=(id,d)=>Math.round(n(id,d));
  return {
    speed:THREE.MathUtils.clamp(n('inSpeed',22),2,45),
    carMass:THREE.MathUtils.clamp(n('inCarMass',1250),300,4000),
    gravity:THREE.MathUtils.clamp(n('inGravity',9.81),1,25),
    trackLength:THREE.MathUtils.clamp(n('inTrack',40),24,80),
    carL:THREE.MathUtils.clamp(n('inCarL',4.2),2.5,6),
    carW:THREE.MathUtils.clamp(n('inCarW',1.8),1.2,2.6),
    carH:THREE.MathUtils.clamp(n('inCarH',1.45),0.9,2.2),
    cols:THREE.MathUtils.clamp(i('inCols',12),4,24),
    rows:THREE.MathUtils.clamp(i('inRows',8),3,16),
    depth:THREE.MathUtils.clamp(i('inDepth',2),1,4),
    brickMass:THREE.MathUtils.clamp(n('inBrickMass',2.5),0.5,12),
    brickW:THREE.MathUtils.clamp(n('inBrickW',0.50),0.2,0.9),
    brickH:THREE.MathUtils.clamp(n('inBrickH',0.24),0.1,0.5),
    brickD:THREE.MathUtils.clamp(n('inBrickD',0.20),0.1,0.5),
    brickFric:THREE.MathUtils.clamp(n('inBrickFric',0.72),0,1.5),
    brickRest:THREE.MathUtils.clamp(n('inBrickRest',0.18),0,0.9),
    groundFric:THREE.MathUtils.clamp(n('inGroundFric',0.85),0,1.5),
  };
}
function clearWorld(){
  if(world){ dyn.forEach(o=>{ if(o.body) world.removeBody(o.body); scene.remove(o.obj); }); }
  dyn=[]; constraints=[]; brickBodies=[]; carParts=[]; wheelSpinners=[]; impacted=false; driveSpeed=0; elapsed=0; shake=0;
  // remove leftover scene children except lights/camera helpers (tagged)
  [...scene.children].forEach(c=>{ if(c.userData && c.userData.temp) scene.remove(c); });
  dust=null; sparks=null;
}
function boxMesh(w,h,d,mat){
  const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);
  m.castShadow=true; m.receiveShadow=true; return m;
}
function addBody(obj, body, isCar=false, name=''){
  world.addBody(body); scene.add(obj); dyn.push({obj,body}); obj.userData.temp=true;
  if(isCar) carParts.push({obj,body,name});
  return body;
}
function addConstraint(a,b,breakVel,label){
  const c=new CANNON.LockConstraint(a,b,{maxForce:1e7});
  world.addConstraint(c);
  const rec={c,a,b,breakVel,label,active:true}; constraints.push(rec); return rec;
}
function breakConstraint(rec){
  if(!rec.active) return; rec.active=false; try{world.removeConstraint(rec.c)}catch(e){}
}
function onCarCollide(selfBody, e){
  const v=Math.abs(e.contact.getImpactVelocityAlongNormal());
  if(v<2.2) return;
  const other=e.body;
  const isHard = brickBodies.includes(other) || other.mass===0;
  if(v>4.5 && brickBodies.includes(other) && !impacted){ impacted=true; shake=Math.min(0.55, v*0.018); spawnDust(selfBody.position, v); spawnSparks(selfBody.position); }
  if(v>4.5 && brickBodies.includes(other)) { shake=Math.max(shake, Math.min(0.4, v*0.012)); }
  // Direct break: finite impulse threshold per joint (breakVel in m/s impact)
  [...constraints].forEach(r=>{
    if(!r.active) return;
    if((r.a===selfBody||r.b===selfBody) && v>r.breakVel) breakConstraint(r);
  });
  // One-hop transmission: neighbours feel attenuated impulse — doors/hood tear without a timer
  if(v>6){
    const neighbours=new Set();
    constraints.forEach(r=>{ if(r.a===selfBody) neighbours.add(r.b); if(r.b===selfBody) neighbours.add(r.a); });
    [...constraints].forEach(r=>{
      if(!r.active) return;
      if((neighbours.has(r.a)||neighbours.has(r.b)) && v>r.breakVel*1.55) breakConstraint(r);
    });
  }
}

/* ---------- Effects (visual only, seeded) ---------- */
function makePoints(count,color,size,opacity){
  const g=new THREE.BufferGeometry(); const pos=new Float32Array(count*3);
  g.setAttribute('position', new THREE.BufferAttribute(pos,3));
  const m=new THREE.PointsMaterial({color,size,transparent:true,opacity,depthWrite:false});
  const p=new THREE.Points(g,m); p.userData.temp=true; scene.add(p); return p;
}
function spawnDust(at,v){
  if(dust) scene.remove(dust); dustVel=[];
  dust=makePoints(90,0xcbb59a,0.55,0.55); const p=dust.geometry.attributes.position.array;
  for(let i=0;i<90;i++){ p[i*3]=at.x+(visRand()-0.5)*1.2; p[i*3+1]=Math.max(0.15,at.y+(visRand()-0.5)*0.8); p[i*3+2]=at.z+(visRand()-0.5)*1.8;
    dustVel.push(new THREE.Vector3((visRand()-0.7)*3, visRand()*2.2+0.5,(visRand()-0.5)*4)); }
  dust.geometry.attributes.position.needsUpdate=true;
}
function spawnSparks(at){
  if(sparks) scene.remove(sparks); sparkVel=[];
  sparks=makePoints(36,0xffc266,0.14,0.95); const p=sparks.geometry.attributes.position.array;
  for(let i=0;i<36;i++){ p[i*3]=at.x; p[i*3+1]=at.y; p[i*3+2]=at.z;
    sparkVel.push(new THREE.Vector3((visRand()-0.5)*7, visRand()*5,(visRand()-0.5)*7)); }
}
function updateEffects(dt){
  [[dust,dustVel,0.92],[sparks,sparkVel,0.82]].forEach(([pts,vels,damp])=>{
    if(!pts) return; const p=pts.geometry.attributes.position.array;
    for(let i=0;i<vels.length;i++){ vels[i].multiplyScalar(damp); vels[i].y-=3*dt*(pts===dust?0.2:1);
      p[i*3]+=vels[i].x*dt; p[i*3+1]=Math.max(0.03,p[i*3+1]+vels[i].y*dt); p[i*3+2]+=vels[i].z*dt; }
    pts.geometry.attributes.position.needsUpdate=true; pts.material.opacity*=0.985;
  });
}

/* ---------- Build experiment ---------- */
function buildExperiment(s){
  settings=s; clearWorld();
  world=new CANNON.World({gravity:new CANNON.Vec3(0,-s.gravity,0)});
  world.broadphase=new CANNON.SAPBroadphase(world); world.allowSleep=true;
  world.solver.iterations=12; world.defaultContactMaterial.friction=s.groundFric;
  const matGround=new CANNON.Material('ground'), matBrick=new CANNON.Material('brick'), matCar=new CANNON.Material('car');
  world.addContactMaterial(new CANNON.ContactMaterial(matBrick,matBrick,{friction:s.brickFric, restitution:s.brickRest}));
  world.addContactMaterial(new CANNON.ContactMaterial(matBrick,matGround,{friction:s.groundFric, restitution:s.brickRest}));
  world.addContactMaterial(new CANNON.ContactMaterial(matCar,matGround,{friction:s.groundFric, restitution:0.04}));
  world.addContactMaterial(new CANNON.ContactMaterial(matCar,matBrick,{friction:s.brickFric, restitution:s.brickRest}));
  world.addContactMaterial(new CANNON.ContactMaterial(matCar,matCar,{friction:0.45, restitution:0.05}));

  const T=s.trackLength; wallX=T/2-5; carStartX=-T/2+5.5;
  // sun frustum tight on track
  sun.position.set(wallX-8,26,12); sun.target.position.set(wallX-10,0,0);
  Object.assign(sun.shadow.camera,{left:-T*0.65,right:T*0.45,top:22,bottom:-22});
  sun.shadow.camera.updateProjectionMatrix();

  // Ground physics (static box)
  const groundBody=new CANNON.Body({mass:0, material:matGround, shape:new CANNON.Box(new CANNON.Vec3(T,0.5,30)), position:new CANNON.Vec3(0,-0.5,0)});
  world.addBody(groundBody);

  /* Environment visuals — static, shared materials, canvas-free merged markings */
  const env=new THREE.Group(); env.userData.temp=true; scene.add(env);
  const asphalt=new THREE.Mesh(new THREE.BoxGeometry(T,0.1,8.4), asphaltMat); asphalt.position.y=-0.05; asphalt.receiveShadow=true; env.add(asphalt);
  const grassGeo=new THREE.BoxGeometry(T+30,0.08,42);
  const grass=new THREE.Mesh(grassGeo, grassMat); grass.position.y=-0.12; grass.receiveShadow=true; // under asphalt, shows as shoulders
  grass.position.z=0; env.add(grass); asphalt.position.z=0;
  // lane markings as thin boxes in one group (static geometry, no shadow casting)
  for(let x=-T/2+2;x<T/2-2;x+=3){ const dash=boxMesh(1.6,0.012,0.16,whiteMat); dash.castShadow=false; dash.position.set(x,0.012,0); env.add(dash); }
  [-3.9,3.9].forEach(z=>{ const line=boxMesh(T-1,0.012,0.14,whiteMat); line.castShadow=false; line.position.set(0,0.012,z); env.add(line); });
  const startLine=boxMesh(0.5,0.014,8.2,whiteMat); startLine.castShadow=false; startLine.position.set(carStartX-2,0.013,0); env.add(startLine);
  // curbs (instanced-style repeated segments)
  for(let x=-T/2;x<T/2;x+=1.2){ [-4.55,4.55].forEach((z,si)=>{ const c=boxMesh(1.18,0.14,0.6, (Math.round(x/1.2)%2===0)?curbRed:curbWhite); c.castShadow=false; c.position.set(x,0.07,z); env.add(c); }); }
  // barriers + light poles
  for(let x=-T/2+4;x<T/2;x+=10){ [-6.2,6.2].forEach(z=>{ const b=boxMesh(3.2,0.55,0.28,barrierMat); b.castShadow=false; b.position.set(x,0.35,z); env.add(b); }); }
  for(let x=-T/2+6;x<T/2;x+=14){ [-6.8,6.8].forEach(z=>{ const pole=new THREE.Mesh(new THREE.CylinderGeometry(0.07,0.07,5.2,8), barrierMat); pole.position.set(x,2.6,z); pole.castShadow=false; env.add(pole);
    const head=boxMesh(0.5,0.16,0.3,lightMat); head.castShadow=false; head.position.set(x,5.2,z*0.92); env.add(head); }); }

  /* Wall — individual staggered bricks, both depth layers real bodies */
  const gap=0.022, bw=s.brickW,bh=s.brickH,bd=s.brickD;
  const wallWidth=s.cols*(bw+gap);
  for(let layer=0; layer<s.depth; layer++){
    for(let row=0; row<s.rows; row++){
      const offset=(row%2===1)? (bw+gap)/2 : 0;
      for(let col=0; col<s.cols; col++){
        const z=-wallWidth/2 + (bw/2) + col*(bw+gap) + offset - offset/ s.cols; // keep centred-ish
        const zz = z - (row%2===1 ? (bw+gap)/4 : 0);
        if(Math.abs(zz)>wallWidth/2) continue;
        const x=wallX + (layer-(s.depth-1)/2)*(bd+gap);
        const y=bh/2 + row*(bh+gap) + 0.001;
        const mesh=boxMesh(bw,bh,bd, brickMats[(row*3+col+layer)%brickMats.length].clone());
        // slight seeded hue shift, visual only
        mesh.material.color.offsetHSL(0,0,(visRand()-0.5)*0.03);
        mesh.position.set(x,y,zz);
